Definition bcell (a : Z) : Prop := (65536 <= a < 0x13a000) \/ (0x695ac0 <= a < 0x695ac8) \/ (0x695d13 <= a < 0x695d14) \/ (0x695df0 <= a < 0x695df4).
Definition lcell (a : Z) : Prop := (0x6742b2 <= a < 0x6749f0) \/ (0x675118 <= a < 0x675170).
Definition scell (a : Z) : Prop := 0x6742b0 <= a < 0x6742b2.
Definition ecell (a : Z) : Prop := (0x674080 <= a < 0x674082) \/ (0x695ad0 <= a < 0x695cf0).

Section Keep.
Variables M M' : word -> option byte.
